"""Second design pass: sculpted silhouettes and controlled optical highlights.
All assets remain path/gradient/filter-only SVG with transparent backgrounds.
"""
import math
REVISIONS={}
def add(id,description,defs,body): REVISIONS[id]=(description,defs,body)

# Plain, static point stars: deliberately no gradients, filters, rays or animation.
body=''.join(f'<circle cx="{x}" cy="{y}" r="{r}" fill="#e2e6ed"/>' for x,y,r in [
 (65,80,2.2),(116,57,1.6),(175,75,3.1),(205,118,1.8),
 (103,119,3.4),(148,128,1.5),(55,146,1.5),(79,185,2.5),
 (132,178,1.9),(187,177,2.8),(159,209,1.4),(119,213,1.2)])
add('stars','A sparse field of clean, static star dots. No glow, flare, diffraction spikes, or twinkle.','',body)

# One continuous cumulus volume, with noise displacement breaking the manufactured outline.
cloud_defs='''<radialGradient id="clouds-main" cx="35%" cy="15%" r="86%"><stop stop-color="#fffffa"/><stop offset=".36" stop-color="#d9e0e4"/><stop offset=".7" stop-color="#9aaabc"/><stop offset="1" stop-color="#425674"/></radialGradient><radialGradient id="clouds-lobe" cx="35%" cy="18%" r="84%"><stop stop-color="#f8f9f4"/><stop offset=".43" stop-color="#d8e1e8"/><stop offset="1" stop-color="#90a0b3" stop-opacity="0"/></radialGradient><linearGradient id="clouds-shade" x2="0" y2="1"><stop offset=".35" stop-color="#354566" stop-opacity="0"/><stop offset="1" stop-color="#22354b" stop-opacity=".65"/></linearGradient><filter id="clouds-contour" x="-15%" y="-20%" width="130%" height="145%"><feTurbulence type="fractalNoise" baseFrequency=".075" numOctaves="3" seed="72" result="n"/><feDisplacementMap in="SourceGraphic" in2="n" scale="5"/><feGaussianBlur stdDeviation=".55"/></filter><filter id="clouds-grain"><feTurbulence type="fractalNoise" baseFrequency=".12" numOctaves="4" seed="52"/><feColorMatrix type="matrix" values="0 0 0 0 .35 0 0 0 0 .44 0 0 0 0 .59 1.2 0 0 0 -.45"/><feComposite in2="SourceGraphic" operator="in"/></filter><clipPath id="clouds-volume"><path d="M63 180C31 179 28 143 47 128q-3-29 24-35 8-25 34-15 14-31 42-16 30-2 35 29 25-3 29 27 31 12 20 40-5 23-36 23Z"/></clipPath>'''
cloud_body='''<g filter="url(#clouds-contour)"><path d="M63 180C31 179 28 143 47 128q-3-29 24-35 8-25 34-15 14-31 42-16 30-2 35 29 25-3 29 27 31 12 20 40-5 23-36 23Z" fill="url(#clouds-main)"/><g clip-path="url(#clouds-volume)"><circle cx="132" cy="103" r="43" fill="url(#clouds-lobe)"/><circle cx="80" cy="118" r="33" fill="url(#clouds-lobe)"/><circle cx="187" cy="140" r="33" fill="url(#clouds-lobe)"/><circle cx="113" cy="149" r="36" fill="url(#clouds-lobe)"/><rect x="23" y="54" width="216" height="135" fill="url(#clouds-shade)"/></g></g>'''
add('clouds','A continuous sculpted cumulus cloud with turbulent edges, illuminated billows, and a soft, dense underside.',cloud_defs,cloud_body)

# Glass-like atmosphere shell with a clear illuminated horizon rather than a dark planet.
add('atmosphere','A translucent atmospheric globe: blue scattering above, a warm horizon, and a cool dusk hemisphere below.','''<radialGradient id="atmosphere-shell" cx="39%" cy="28%" r="75%"><stop stop-color="#4c7897" stop-opacity=".12"/><stop offset=".6" stop-color="#183754" stop-opacity=".28"/><stop offset=".84" stop-color="#4484b7" stop-opacity=".48"/><stop offset=".95" stop-color="#b2e3f5" stop-opacity=".7"/><stop offset="1" stop-color="#557d9c" stop-opacity=".2"/></radialGradient><linearGradient id="atmosphere-band" x2="0" y2="1"><stop stop-color="#7cb6e2" stop-opacity="0"/><stop offset=".3" stop-color="#88bde2" stop-opacity=".3"/><stop offset=".6" stop-color="#e9d5b9" stop-opacity=".8"/><stop offset=".67" stop-color="#fce6bf"/><stop offset=".72" stop-color="#e7b988" stop-opacity=".55"/><stop offset="1" stop-color="#384668" stop-opacity="0"/></linearGradient><filter id="atmosphere-soft"><feGaussianBlur stdDeviation="3"/></filter><clipPath id="atmosphere-clip"><circle cx="128" cy="128" r="79"/></clipPath>''','''<circle cx="128" cy="128" r="79" fill="url(#atmosphere-shell)"/><g clip-path="url(#atmosphere-clip)"><path d="M42 163q88-44 172 0v39H42Z" fill="#182b40"/><path d="M40 145q86-54 176-3v40q-88-39-176 0Z" fill="url(#atmosphere-band)" filter="url(#atmosphere-soft)"/><path d="M48 162q80-41 160 0" stroke="#fae5c8" stroke-width="1.2" opacity=".8"/><path d="M55 101q56-46 121-14" stroke="#b7e9ff" stroke-opacity=".22" stroke-width=".8"/></g><path d="M63 83a79 79 0 0 1 117-14" stroke="#b6e9ff" stroke-opacity=".5" stroke-width="1.1"/><circle cx="128" cy="128" r="84" stroke="#729ec3" stroke-opacity=".12" stroke-width=".65"/>''')

# Weather reuses the improved cloud volume, not an unrelated cloud silhouette.
rain_defs=cloud_defs.replace('clouds-','precip-cloud-')+'''<radialGradient id="precip-drop" cx="25%" cy="20%" r="85%"><stop stop-color="#f5ffff"/><stop offset=".35" stop-color="#9cd8f5"/><stop offset=".8" stop-color="#4b95c4"/><stop offset="1" stop-color="#c5eaff"/></radialGradient><linearGradient id="precip-trail" x2="0" y2="1"><stop stop-color="#7bb9df" stop-opacity="0"/><stop offset="1" stop-color="#aedffd" stop-opacity=".45"/></linearGradient>'''
body='<g transform="translate(24 -4) scale(.81)">'+cloud_body.replace('clouds-','precip-cloud-')+'</g>'
for x,y,r in [(87,167,7),(132,184,9),(177,170,6)]:
 body+=f'<path d="M{x+7} {y-19}L{x} {y-3}" stroke="url(#precip-trail)" stroke-width="1.2"/><path d="M{x} {y-r*1.5}C{x+r*.25} {y-r*.7} {x+r} {y} {x+r} {y+r*.4}A{r} {r} 0 0 1 {x-r} {y+r*.4}C{x-r} {y} {x-r*.25} {y-r*.7} {x} {y-r*1.5}Z" fill="url(#precip-drop)" transform="rotate(19 {x} {y})"/>'
add('precipitation','Soft storm-cloud shading and falling glassy droplets, with separate specular rims and faint rain trails.',rain_defs,body)

# A curling crest is far more legible as water than the old isometric block.
add('water','A sculpted curling wave, with turquoise transmitted light, deep-blue troughs, and a finely feathered foam lip.','''<linearGradient id="water-crest" x1=".1" y1=".1" x2=".8" y2="1"><stop stop-color="#e1faf4"/><stop offset=".2" stop-color="#8bded8"/><stop offset=".5" stop-color="#3c9fac"/><stop offset=".8" stop-color="#1c566f"/><stop offset="1" stop-color="#19394f"/></linearGradient><linearGradient id="water-curl" x2="1" y2="1"><stop stop-color="#bdf5eb"/><stop offset=".48" stop-color="#519fae"/><stop offset="1" stop-color="#153c54"/></linearGradient><filter id="water-foam"><feTurbulence baseFrequency=".17" numOctaves="2" seed="8" result="n"/><feDisplacementMap in="SourceGraphic" in2="n" scale="2.5"/></filter>''','''<path d="M32 171c28 4 44-12 59-41 14-30 18-62 53-66 36-3 62 21 54 45-5 20-30 28-44 15 23 1 30-19 15-28-22-13-34 23-23 45 11 22 44 30 78 35-54 34-128 39-192-5Z" fill="url(#water-crest)"/><path d="M91 130c14-30 18-62 53-66 36-3 62 21 54 45-5 20-30 28-44 15 23 1 30-19 15-28-22-13-34 23-23 45" fill="url(#water-curl)"/><path d="M94 127c13-32 21-56 51-59 30-3 54 17 50 39" stroke="#f1fff5" stroke-width="3" stroke-opacity=".82" filter="url(#water-foam)"/><path d="M47 173q40 9 71-5m-55 14q51 11 107-1m-42-86q-18 33-5 58m15-63q-10 34 3 54" stroke="#bdece9" stroke-opacity=".3" stroke-width="1" stroke-linecap="round"/><path d="M37 183q73 30 178-1" stroke="#98d8e0" stroke-opacity=".25" stroke-width="1.2"/>''')

# Neutral chrome avoids the muddy copper palette of the first material sample.
add('material','A polished chrome material sphere with curved studio-panel reflections and a clear, pale-blue edge coat.','''<radialGradient id="material-chrome" cx="32%" cy="25%" r="78%"><stop stop-color="#dbe7ee"/><stop offset=".16" stop-color="#8ea6b9"/><stop offset=".34" stop-color="#243a50"/><stop offset=".52" stop-color="#111d2a"/><stop offset=".65" stop-color="#7295b3"/><stop offset=".79" stop-color="#d8e8eb"/><stop offset=".9" stop-color="#485e72"/><stop offset="1" stop-color="#192434"/></radialGradient><linearGradient id="material-window" x2=".7" y2="1"><stop stop-color="#fffdf4"/><stop offset=".75" stop-color="#dce8ef"/><stop offset="1" stop-color="#a6c7df" stop-opacity=".1"/></linearGradient><clipPath id="material-ball"><circle cx="128" cy="122" r="76"/></clipPath><filter id="material-window-soft"><feGaussianBlur stdDeviation=".7"/></filter><radialGradient id="material-pedestal"><stop stop-color="#8c99a3" stop-opacity=".45"/><stop offset="1" stop-color="#32445a" stop-opacity="0"/></radialGradient>''','''<circle cx="128" cy="122" r="76" fill="url(#material-chrome)"/><g clip-path="url(#material-ball)" filter="url(#material-window-soft)"><path d="M68 89q20-36 64-34l-18 30q-29 0-46 17Z" fill="url(#material-window)"/><path d="M75 114q11-12 33-15l-12 18q-11 1-21 8Z" fill="#e4f0f8" opacity=".58"/><path d="M185 77q33 62-8 98l-8-4q40-39 8-91Z" fill="#e2f2ff" opacity=".67"/><path d="M66 158q39 36 115 13l-2 9q-66 31-109-9Z" fill="#101b2b" opacity=".55"/></g><circle cx="128" cy="122" r="76" stroke="#d1e6f5" stroke-opacity=".48" stroke-width=".7"/>''')

# Lens-first camera, with mechanical ring detail rather than a flat toy body.
camera_defs='''<linearGradient id="camera-metal" x2=".6" y2="1"><stop stop-color="#596372"/><stop offset=".28" stop-color="#333b46"/><stop offset="1" stop-color="#111923"/></linearGradient><radialGradient id="camera-barrel"><stop offset=".6" stop-color="#1a2530"/><stop offset=".73" stop-color="#647383"/><stop offset=".78" stop-color="#151c27"/><stop offset=".86" stop-color="#778898"/><stop offset=".9" stop-color="#263340"/><stop offset="1" stop-color="#0d151e"/></radialGradient><radialGradient id="camera-optic" cx="36%" cy="30%" r="78%"><stop stop-color="#79a9b9" stop-opacity=".8"/><stop offset=".2" stop-color="#344465"/><stop offset=".55" stop-color="#152038"/><stop offset=".8" stop-color="#172c3e"/><stop offset="1" stop-color="#5b788b"/></radialGradient><linearGradient id="camera-reflection" x2="1" y2="1"><stop stop-color="#e7ffff" stop-opacity=".65"/><stop offset="1" stop-color="#9b79c8" stop-opacity="0"/></linearGradient>'''
body='''<path d="M42 96q0-10 11-10h42l12-20h45l13 20h40q10 0 10 11v80q0 11-12 11H51q-11 0-11-12Z" fill="url(#camera-metal)" stroke="#8494a2" stroke-opacity=".25"/><path d="M46 105v65q0 6 6 6h19v-75H52q-6 0-6 4Z" fill="#101923"/><path d="M51 112v51m5-51v51m5-51v51" stroke="#84949e" stroke-opacity=".1" stroke-width="1"/><path d="M107 76h39" stroke="#8795a3" stroke-width="3" stroke-opacity=".3"/><rect x="64" y="80" width="18" height="5" rx="2" fill="#8e99a0"/><circle cx="139" cy="137" r="54" fill="url(#camera-barrel)"/>'''
for i in range(48):body+=f'<path d="M139 85v3" transform="rotate({i*7.5} 139 137)" stroke="#a0b1bc" stroke-opacity=".3" stroke-width=".7"/>'
body+='''<circle cx="139" cy="137" r="35" fill="url(#camera-optic)" stroke="#95b2c5" stroke-opacity=".35"/><circle cx="139" cy="137" r="16" fill="#08111d"/><path d="M113 122q10-19 34-15l-12 15q-13 0-22 10Z" fill="url(#camera-reflection)"/><path d="M158 145q6 8-5 15" stroke="#ad83cc" stroke-opacity=".35" stroke-width="3" stroke-linecap="round"/><circle cx="193" cy="101" r="3" fill="#849eaa"/><path d="M188 173h14" stroke="#798897" stroke-opacity=".25"/>'''
add('camera','A lens-first camera with machined barrel ticks, coated optics, dark aperture glass, and a textured grip.',camera_defs,body)

# Optical ghosts share a single axis through the light source and image centre.
# Layered spectral rims and veiling glare replace decorative starburst lines.
flare_defs='''<radialGradient id="flare-source"><stop stop-color="#ffffff"/><stop offset=".025" stop-color="#fffde9"/><stop offset=".07" stop-color="#fff0bd" stop-opacity=".95"/><stop offset=".18" stop-color="#ffd18b" stop-opacity=".6"/><stop offset=".4" stop-color="#ed9147" stop-opacity=".18"/><stop offset="1" stop-color="#b74528" stop-opacity="0"/></radialGradient>
<radialGradient id="flare-veil"><stop stop-color="#e4bba4" stop-opacity=".13"/><stop offset="1" stop-color="#a67193" stop-opacity="0"/></radialGradient>
<radialGradient id="flare-large-ghost"><stop stop-color="#83c5b8" stop-opacity=".035"/><stop offset=".65" stop-color="#88c9a8" stop-opacity=".065"/><stop offset=".82" stop-color="#99d5ae" stop-opacity=".19"/><stop offset=".9" stop-color="#a2deb9" stop-opacity=".32"/><stop offset=".95" stop-color="#daca83" stop-opacity=".27"/><stop offset=".98" stop-color="#df9286" stop-opacity=".13"/><stop offset="1" stop-color="#c28ba7" stop-opacity="0"/></radialGradient>
<radialGradient id="flare-small-ghost"><stop stop-color="#77b9c8" stop-opacity=".08"/><stop offset=".72" stop-color="#79b8dc" stop-opacity=".24"/><stop offset=".9" stop-color="#b3c4ed" stop-opacity=".5"/><stop offset="1" stop-color="#867acb" stop-opacity="0"/></radialGradient>
<radialGradient id="flare-iris"><stop stop-color="#b6cc83" stop-opacity=".07"/><stop offset=".8" stop-color="#c9d7a1" stop-opacity=".13"/><stop offset="1" stop-color="#c0c989" stop-opacity=".28"/></radialGradient>
<linearGradient id="flare-streak" gradientUnits="userSpaceOnUse" x1="13" y1="87" x2="203" y2="87"><stop stop-color="#82a7cb" stop-opacity="0"/><stop offset=".23" stop-color="#acd5eb" stop-opacity=".12"/><stop offset=".34" stop-color="#fff8e5" stop-opacity=".9"/><stop offset=".43" stop-color="#add9ef" stop-opacity=".35"/><stop offset="1" stop-color="#718dbb" stop-opacity="0"/></linearGradient>
<filter id="flare-soft"><feGaussianBlur stdDeviation=".7"/></filter>'''
flare_body='''<circle cx="119" cy="126" r="103" fill="url(#flare-veil)"/>
<circle cx="185" cy="174" r="49" fill="url(#flare-large-ghost)"/>
<g filter="url(#flare-soft)"><path d="m153 134 16 9v18l-16 9-16-9v-18Z" fill="url(#flare-iris)"/><circle cx="125" cy="125" r="8" fill="url(#flare-small-ghost)"/><circle cx="107" cy="111" r="3.2" fill="#d7e7b5" opacity=".36"/><circle cx="210" cy="194" r="9" fill="url(#flare-small-ghost)"/></g>
<circle cx="77" cy="87" r="66" fill="url(#flare-source)"/>
<path d="M13 87h190" stroke="url(#flare-streak)" stroke-width="1"/>
<circle cx="77" cy="87" r="1.5" fill="#fffef7"/>'''
add('lens-flare','A bright photographic light source with soft veiling glare and spectrally edged aperture reflections aligned along the optical axis.',flare_defs,flare_body)

add('folder','A folded, dimensional folder with visible document layers and an angled front panel, finished in warm anodized gold.','''<linearGradient id="folder-back" x2=".6" y2="1"><stop stop-color="#d3b97d"/><stop offset="1" stop-color="#5c472c"/></linearGradient><linearGradient id="folder-front" x2=".2" y2="1"><stop stop-color="#f1dba6"/><stop offset=".14" stop-color="#d0ac69"/><stop offset=".55" stop-color="#a78345"/><stop offset="1" stop-color="#68522f"/></linearGradient><linearGradient id="folder-paper" x2="0" y2="1"><stop stop-color="#dedfd5"/><stop offset="1" stop-color="#8c9693"/></linearGradient>''','''<path d="M43 71q0-7 8-7h45l17 15h91q8 0 8 9v101H43Z" fill="url(#folder-back)" stroke="#e8cf9a" stroke-opacity=".24"/><path d="m53 86 139-5 3 102-139 5Z" fill="#b1b7b1"/><path d="m63 85 133 9-7 87-132-9Z" fill="url(#folder-paper)"/><path d="m74 100 97 6m-98 3 79 5m-80 4 88 6" stroke="#667979" stroke-opacity=".22" stroke-width="1.1"/><path d="m38 116 149 10q5 0 9-5l11-10 18 1-18 74q-2 8-10 8H48q-8 0-9-9l-9-59q-2-10 8-10Z" fill="url(#folder-front)" stroke="#f1d49a" stroke-opacity=".35"/><path d="m39 120 148 10q9 0 18-14" stroke="#ffeac0" stroke-opacity=".47" stroke-width="1"/><path d="M47 187h151" stroke="#493923" stroke-opacity=".4"/><rect x="56" y="164" width="30" height="4" rx="2" fill="#e5cb94" opacity=".2"/>''')

# Collections are discrete linked objects, avoiding the previous layer-stack metaphor.
collection_defs='''<linearGradient id="collection-top" x2="1" y2="1"><stop stop-color="#e4d4f4"/><stop offset="1" stop-color="#9c84bd"/></linearGradient><linearGradient id="collection-left" x2="0" y2="1"><stop stop-color="#a996c4"/><stop offset="1" stop-color="#544267"/></linearGradient><linearGradient id="collection-right" x2="1" y2="1"><stop stop-color="#77618f"/><stop offset="1" stop-color="#34273f"/></linearGradient>'''
def cube(x,y,s):return f'<g transform="translate({x} {y}) scale({s})"><path d="m0-33 31 17L0 1-31-17Z" fill="url(#collection-top)"/><path d="M-31-17 0 1v35l-31-18Z" fill="url(#collection-left)"/><path d="M0 1 31-17v35L0 36Z" fill="url(#collection-right)"/><path d="m-31-17 31 18 31-18M0 1v35" stroke="#ead8f9" stroke-opacity=".36" stroke-width=".8"/></g>'
body='<path d="M82 151 128 88l46 63M82 151h92" stroke="#aa8bca" stroke-opacity=".26" stroke-width="2"/>'+cube(128,80,.95)+cube(78,162,.95)+cube(181,162,.95)
add('collection','Three separate sculpted objects joined by a subtle reference triangle—grouping without implying a physical folder.',collection_defs,body)

from icon_reference_revision import REVISIONS as REFERENCE_REVISIONS
REVISIONS.update(REFERENCE_REVISIONS)
